class Solution {
    public boolean exist(char[][] board, String word) {
        int m = board.length, n = board[0].length;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (dfs(board, word, i, j, 0)) return true;
            }
        }
        return false;
    }

    private boolean dfs(char[][] board, String word, int i, int j, int k) {
        if (k == word.length()) return true;
        if (i < 0 || i >= board.length || j < 0 || j >= board[0].length) return false;
        if (board[i][j] != word.charAt(k)) return false;
        char tmp = board[i][j];
        board[i][j] = '#';
        boolean found = dfs(board, word, i + 1, j, k + 1)
                      || dfs(board, word, i - 1, j, k + 1)
                      || dfs(board, word, i, j + 1, k + 1)
                      || dfs(board, word, i, j - 1, k + 1);
        board[i][j] = tmp;
        return found;
    }
}

class Solution {
    public boolean exist(char[][] board, String word) {
        int m = board.length, n = board[0].length;
        int[] freq = new int[128];
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                freq[board[i][j]]++;
        int[] need = new int[128];
        for (char c : word.toCharArray()) need[c]++;
        for (int i = 0; i < 128; i++)
            if (need[i] > freq[i]) return false;
        char[] chars = word.toCharArray();
        if (freq[chars[0]] > freq[chars[chars.length - 1]]) {
            int left = 0, right = chars.length - 1;
            while (left < right) {
                char tmp = chars[left];
                chars[left] = chars[right];
                chars[right] = tmp;
                left++;
                right--;
            }
        }
        boolean[][] visited = new boolean[m][n];
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (search(board, chars, i, j, 0, visited)) return true;
        return false;
    }

    private boolean search(char[][] board, char[] word, int i, int j, int k, boolean[][] visited) {
        if (k == word.length) return true;
        if (i < 0 || i >= board.length || j < 0 || j >= board[0].length) return false;
        if (visited[i][j] || board[i][j] != word[k]) return false;
        visited[i][j] = true;
        boolean found = search(board, word, i + 1, j, k + 1, visited)
                      || search(board, word, i - 1, j, k + 1, visited)
                      || search(board, word, i, j + 1, k + 1, visited)
                      || search(board, word, i, j - 1, k + 1, visited);
        visited[i][j] = false;
        return found;
    }
}
